contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (1));
        require(address(this).balance >= 1);
        c.deposit{value: 1}(); if (__ESBMC_reverted()) return;
        uint256 preBalance = address(c).balance;
        bool reverted;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted ? address(c).balance == preBalance : address(c).balance == 0);
    }

    receive() external payable {}
}

